#include <string>
#include <unordered_map>
#include <sstream>

using namespace std;

class Spreadsheet {
    int maxRows;
    unordered_map<string, int> grid;

public:
    Spreadsheet(int rows) : maxRows(rows) {}

    void setCell(string cell, int value) {
        grid[cell] = value;
    }

    void resetCell(string cell) {
        grid.erase(cell);
    }

    int getValue(string formula) {
        string expr = formula.substr(1);
        stringstream ss(expr);
        string part;
        int total = 0;
        while (getline(ss, part, '+')) {
            if (isalpha(part[0])) {
                if (grid.count(part)) total += grid[part];
            } else {
                total += stoi(part);
            }
        }
        return total;
    }
};

import java.util.HashMap;
import java.util.Map;

class Spreadsheet {
    private int maxRows;
    private Map<String, Integer> grid = new HashMap<>();

    public Spreadsheet(int rows) {
        this.maxRows = rows;
    }

    public void setCell(String cell, int value) {
        grid.put(cell, value);
    }

    public void resetCell(String cell) {
        grid.remove(cell);
    }

    public int getValue(String formula) {
        String expr = formula.substring(1);
        String[] parts = expr.split("\\+");
        int total = 0;
        for (String p : parts) {
            if (Character.isLetter(p.charAt(0))) {
                total += grid.getOrDefault(p, 0);
            } else {
                total += Integer.parseInt(p);
            }
        }
        return total;
    }
}

/**
 * @param {number} rows
 */
var Spreadsheet = function(rows) {
    this.rows = rows;
    this.grid = new Map();
};

/** 
 * @param {string} cell 
 * @param {number} value
 * @return {void}
 */
Spreadsheet.prototype.setCell = function(cell, value) {
    this.grid.set(cell, value);
};

/** 
 * @param {string} cell
 * @return {void}
 */
Spreadsheet.prototype.resetCell = function(cell) {
    this.grid.delete(cell);
};

/** 
 * @param {string} formula
 * @return {number}
 */
Spreadsheet.prototype.getValue = function(formula) {
    const expr = formula.substring(1);
    const parts = expr.split('+');
    let total = 0;
    for (const p of parts) {
        if (/^[A-Za-z]/.test(p)) {
            total += (this.grid.get(p) || 0);
        } else {
            total += parseInt(p, 10);
        }
    }
    return total;
};
